CREATE FUNCTION public.validar_configuracoes() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; v int; BEGIN IF (NEW.ferias_inicio IS NULL)<>(NEW.ferias_fim IS NULL) OR NEW.ferias_inicio>NEW.ferias_fim THEN RAISE EXCEPTION 'Informe um período de férias válido'; END IF; IF cardinality(NEW.cadencia_intervalos)<1 OR EXISTS(SELECT 1 FROM unnest(NEW.cadencia_intervalos) x WHERE x IS NULL OR x<1) THEN RAISE EXCEPTION 'Cadência deve conter intervalos positivos'; END IF; FOREACH k IN ARRAY ARRAY['contramarco','apto_modelo','andar_tipo','area_comum','especiais','reposicao'] LOOP v=(NEW.prazos->>k)::int; IF v IS NULL OR v<0 THEN RAISE EXCEPTION 'Prazo inválido para %',k; END IF; END LOOP; RETURN NEW; END $$;
CREATE TRIGGER configuracoes_validar BEFORE INSERT OR UPDATE ON public.configuracoes FOR EACH ROW EXECUTE FUNCTION public.validar_configuracoes();
CREATE FUNCTION public.calcular_lote() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c public.configuracoes; fim date; BEGIN SELECT * INTO STRICT c FROM public.configuracoes WHERE id=1; IF NEW.prazo_dias IS NULL THEN NEW.prazo_dias=(c.prazos->>NEW.tipo::text)::int; END IF; IF NEW.entregue_em IS NOT NULL THEN NEW.status='entregue'; ELSIF NEW.status NOT IN ('pcp','em_producao','produzido') THEN IF NOT NEW.cadastro_completo THEN NEW.status='aguardando_cadastro'; ELSIF NEW.medido_em IS NOT NULL THEN IF NEW.status IN ('aguardando_cadastro','aguardando_medicao','medicao_agendada','entregue') THEN NEW.status='medido'; END IF; ELSIF NEW.previsao_medicao IS NOT NULL THEN NEW.status='medicao_agendada'; ELSE NEW.status='aguardando_medicao'; END IF; END IF; NEW.acrescimo_ferias_dias=0; NEW.ferias_pendente=false; IF NEW.medido_em IS NOT NULL THEN fim=NEW.medido_em+NEW.prazo_dias; IF c.ferias_inicio IS NULL OR c.ferias_fim IS NULL THEN NEW.ferias_pendente=true; ELSIF NEW.medido_em<=c.ferias_fim AND fim>=c.ferias_inicio THEN NEW.acrescimo_ferias_dias=c.acrescimo_ferias_dias; END IF; NEW.previsao_entrega=fim+NEW.acrescimo_ferias_dias; ELSE NEW.previsao_entrega=NULL; END IF; RETURN NEW; END $$;
CREATE TRIGGER lotes_calcular BEFORE INSERT OR UPDATE ON public.lotes FOR EACH ROW EXECUTE FUNCTION public.calcular_lote();
CREATE FUNCTION public.recalcular_lotes() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN UPDATE public.lotes SET prazo_dias=(NEW.prazos->>tipo::text)::int WHERE medido_em IS NOT NULL AND entregue_em IS NULL; RETURN NEW; END $$;
CREATE TRIGGER configuracoes_recalcular AFTER UPDATE OF prazos,ferias_inicio,ferias_fim,acrescimo_ferias_dias ON public.configuracoes FOR EACH ROW EXECUTE FUNCTION public.recalcular_lotes();
CREATE FUNCTION public.inicializar_obra() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE dias int; BEGIN SELECT dias_tarefa_inicial INTO STRICT dias FROM public.configuracoes WHERE id=1; INSERT INTO public.checklist_itens(obra_id,ordem,item) SELECT NEW.id,n,item FROM unnest(ARRAY['Confirmar necessidade de acústica e ventilação','Construtora tem consultor próprio de esquadrias? Se sim, informar a Prado','Cadastro do pedido completo','Solicitar laudos e ARTs','Cronograma com datas e quantidades assinado pelo cliente','Lotes cadastrados e medição do primeiro lote agendada','Solicitar treinamento de instalação','Informar a Prado que a obra está instalando','Revisão de 40 dias: regulagem pelos técnicos e fotos da limpeza geral']) WITH ORDINALITY AS t(item,n); INSERT INTO public.followups(obra_id,cliente_id,data,motivo,origem) SELECT NEW.id,NEW.cliente_id,public.hoje_sp()+dias,m,'automatico' FROM unnest(ARRAY['Solicitar laudos e ARTs','Cadastrar pedido completo','Agendar medição']) m; RETURN NEW; END $$;
CREATE TRIGGER obras_inicializar AFTER INSERT ON public.obras FOR EACH ROW EXECUTE FUNCTION public.inicializar_obra();
CREATE FUNCTION public.agendar_revisao() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.finalizada_em IS NULL AND NEW.finalizada_em IS NOT NULL THEN INSERT INTO public.followups(obra_id,cliente_id,data,motivo,origem) SELECT NEW.id,NEW.cliente_id,NEW.finalizada_em+revisao_dias,'Revisão de 40 dias: regulagem e fotos da limpeza','automatico' FROM public.configuracoes WHERE id=1; END IF; RETURN NEW; END $$;
CREATE TRIGGER obras_revisao AFTER UPDATE ON public.obras FOR EACH ROW EXECUTE FUNCTION public.agendar_revisao();
CREATE FUNCTION public.buscar_clientes(p_texto text,p_limite int DEFAULT 10) RETURNS TABLE(id uuid,nome text,situacao_prado public.situacao_prado,representante_prado text,similaridade real) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t text; BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; t=public.normalizar_texto(p_texto); RETURN QUERY SELECT c.id,c.nome,c.situacao_prado,c.representante_prado,extensions.similarity(c.nome_normalizado,t) FROM public.clientes c WHERE t<>'' AND (position(t in c.nome_normalizado)>0 OR extensions.similarity(c.nome_normalizado,t)>=0.3) ORDER BY extensions.similarity(c.nome_normalizado,t) DESC,c.nome LIMIT greatest(1,least(coalesce(p_limite,10),100)); END $$;
CREATE FUNCTION public.buscar_contato_por_whatsapp(p_numero text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.contatos; BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; SELECT * INTO c FROM public.contatos WHERE whatsapp=public.whatsapp_normalizado(p_numero); IF NOT FOUND THEN RETURN NULL; END IF; RETURN jsonb_build_object('contato',to_jsonb(c),'cliente',(SELECT to_jsonb(x) FROM public.clientes x WHERE x.id=c.cliente_id),'oportunidades',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.oportunidades x WHERE x.contato_id=c.id),'[]'::jsonb),'followup_pendente',(SELECT to_jsonb(x) FROM public.followups x WHERE x.contato_id=c.id AND x.status='pendente' ORDER BY (x.origem='prospeccao') DESC,x.data,x.created_at LIMIT 1)); END $$;
CREATE FUNCTION public.mesclar_clientes(p_manter uuid,p_remover uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE nome_removido text; BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; IF p_manter IS NULL OR p_remover IS NULL OR p_manter=p_remover THEN RAISE EXCEPTION 'Informe dois clientes diferentes'; END IF; PERFORM id FROM public.clientes WHERE id IN(p_manter,p_remover) ORDER BY id FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.clientes WHERE id=p_manter) THEN RAISE EXCEPTION 'Cliente a manter não encontrado'; END IF; SELECT nome INTO STRICT nome_removido FROM public.clientes WHERE id=p_remover; UPDATE public.contatos SET cliente_id=p_manter WHERE cliente_id=p_remover; UPDATE public.oportunidades SET cliente_id=p_manter WHERE cliente_id=p_remover; UPDATE public.obras SET cliente_id=p_manter WHERE cliente_id=p_remover; UPDATE public.registros SET cliente_id=p_manter WHERE cliente_id=p_remover; UPDATE public.followups SET cliente_id=p_manter WHERE cliente_id=p_remover; INSERT INTO public.registros(cliente_id,tipo,texto) VALUES(p_manter,'nota','Mesclado com '||nome_removido); DELETE FROM public.clientes WHERE id=p_remover; END $$;
CREATE FUNCTION public.registrar_envio(p_contato_id uuid,p_canal public.tipo_registro,p_oportunidade_id uuid DEFAULT NULL,p_texto text DEFAULT NULL,p_data_proxima date DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.contatos; cfg public.configuracoes; n int; d date; m text; BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; SELECT * INTO STRICT c FROM public.contatos WHERE id=p_contato_id FOR UPDATE; SELECT * INTO STRICT cfg FROM public.configuracoes WHERE id=1; IF p_oportunidade_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.oportunidades o WHERE o.id=p_oportunidade_id AND o.cliente_id=c.cliente_id AND (o.contato_id IS NULL OR o.contato_id=c.id)) THEN RAISE EXCEPTION 'Oportunidade incompatível com contato'; END IF; INSERT INTO public.registros(contato_id,cliente_id,oportunidade_id,tipo,direcao,texto) VALUES(c.id,c.cliente_id,p_oportunidade_id,p_canal,'enviado',p_texto); UPDATE public.followups SET status='concluido',concluido_em=now() WHERE contato_id=c.id AND origem='prospeccao' AND status='pendente'; n=c.tentativas_sem_resposta+1; IF n<cfg.cadencia_max_tentativas THEN d=public.hoje_sp()+coalesce(cfg.cadencia_intervalos[n],cfg.cadencia_intervalos[array_upper(cfg.cadencia_intervalos,1)]); m='Follow-up (tentativa '||n||')'; UPDATE public.contatos SET tentativas_sem_resposta=n WHERE id=c.id; ELSE d=public.hoje_sp()+cfg.cadencia_pausa_dias; m='Retomar após pausa'; UPDATE public.contatos SET tentativas_sem_resposta=0 WHERE id=c.id; END IF; INSERT INTO public.followups(contato_id,cliente_id,oportunidade_id,data,motivo,origem,tentativa) VALUES(c.id,c.cliente_id,p_oportunidade_id,coalesce(p_data_proxima,d),m,'prospeccao',n); END $$;
CREATE FUNCTION public.registrar_resposta(p_contato_id uuid,p_canal public.tipo_registro,p_situacao text,p_oportunidade_id uuid DEFAULT NULL,p_necessidade date DEFAULT NULL,p_data_proxima date DEFAULT NULL,p_representante text DEFAULT NULL,p_texto text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.contatos; cfg public.configuracoes; d date; m text; e public.etapa_comercial; necessidade date; BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; SELECT * INTO STRICT c FROM public.contatos WHERE id=p_contato_id FOR UPDATE; SELECT * INTO STRICT cfg FROM public.configuracoes WHERE id=1; IF p_oportunidade_id IS NOT NULL THEN PERFORM id FROM public.oportunidades WHERE id=p_oportunidade_id AND cliente_id=c.cliente_id AND (contato_id IS NULL OR contato_id=c.id) FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Oportunidade incompatível com contato'; END IF; END IF; CASE p_situacao WHEN 'tem_demanda' THEN e='orcamento'; d=public.hoje_sp()+2; m='Acompanhar orçamento'; WHEN 'demanda_prevista' THEN IF p_necessidade IS NULL THEN RAISE EXCEPTION 'Informe o mês da demanda'; END IF; necessidade=date_trunc('month',p_necessidade)::date; e='demanda_prevista'; d=greatest(public.hoje_sp()+1,necessidade-cfg.demanda_antecedencia_dias); m='Acompanhar demanda prevista'; WHEN 'sem_demanda' THEN e='aguardando_demanda'; d=public.hoje_sp()+cfg.retomar_sem_demanda_dias; m='Retomar contato sem demanda'; WHEN 'atendido_outro_rep_prado' THEN IF c.cliente_id IS NULL THEN RAISE EXCEPTION 'Contato sem cliente'; END IF; UPDATE public.clientes SET situacao_prado='atendida_outro_rep',representante_prado=p_representante WHERE id=c.cliente_id; d=p_data_proxima; m='Retomar contato'; WHEN 'falar_depois' THEN IF p_data_proxima IS NULL THEN RAISE EXCEPTION 'Informe a próxima data'; END IF; d=p_data_proxima; m='Retomar contato'; WHEN 'sem_interesse' THEN e='perdido'; ELSE RAISE EXCEPTION 'Situação inválida'; END CASE; INSERT INTO public.registros(contato_id,cliente_id,oportunidade_id,tipo,direcao,texto) VALUES(c.id,c.cliente_id,p_oportunidade_id,p_canal,'recebido',p_texto); UPDATE public.followups SET status='concluido',concluido_em=now() WHERE contato_id=c.id AND origem='prospeccao' AND status='pendente'; UPDATE public.contatos SET tentativas_sem_resposta=0 WHERE id=c.id; IF p_oportunidade_id IS NOT NULL AND e IS NOT NULL THEN UPDATE public.oportunidades SET etapa=e,necessidade_prevista=CASE WHEN e='demanda_prevista' THEN necessidade ELSE necessidade_prevista END WHERE id=p_oportunidade_id; END IF; IF p_situacao<>'sem_interesse' AND coalesce(p_data_proxima,d) IS NOT NULL THEN INSERT INTO public.followups(contato_id,cliente_id,oportunidade_id,data,motivo,origem) VALUES(c.id,c.cliente_id,p_oportunidade_id,coalesce(p_data_proxima,d),m,'prospeccao'); END IF; END $$;
CREATE FUNCTION public.concluir_followup(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; UPDATE public.followups SET status='concluido',concluido_em=now() WHERE id=p_id AND status='pendente'; IF NOT FOUND THEN RAISE EXCEPTION 'Follow-up pendente não encontrado'; END IF; END $$;
CREATE FUNCTION public.cancelar_followup(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; UPDATE public.followups SET status='cancelado',concluido_em=NULL WHERE id=p_id AND status='pendente'; IF NOT FOUND THEN RAISE EXCEPTION 'Follow-up pendente não encontrado'; END IF; END $$;
CREATE FUNCTION public.remarcar_followup(p_id uuid,p_data date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; IF p_data IS NULL THEN RAISE EXCEPTION 'Informe a data'; END IF; UPDATE public.followups SET data=p_data WHERE id=p_id AND status='pendente'; IF NOT FOUND THEN RAISE EXCEPTION 'Follow-up pendente não encontrado'; END IF; END $$;
CREATE FUNCTION public.marcar_problema(p_obra_id uuid,p_texto text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; IF nullif(trim(p_texto),'') IS NULL THEN RAISE EXCEPTION 'Informe o problema'; END IF; UPDATE public.obras SET problema_ativo=true,problema_texto=p_texto WHERE id=p_obra_id; IF NOT FOUND THEN RAISE EXCEPTION 'Obra não encontrada'; END IF; INSERT INTO public.registros(obra_id,tipo,texto) VALUES(p_obra_id,'problema',p_texto); END $$;
CREATE FUNCTION public.resolver_problema(p_obra_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; UPDATE public.obras SET problema_ativo=false WHERE id=p_obra_id; IF NOT FOUND THEN RAISE EXCEPTION 'Obra não encontrada'; END IF; INSERT INTO public.registros(obra_id,tipo,texto) VALUES(p_obra_id,'nota','Problema resolvido'); END $$;
CREATE FUNCTION public.iniciar_gestao_obra(p_oportunidade_id uuid,p_nome text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.oportunidades; novo uuid; BEGIN IF NOT public.is_authorized() THEN RAISE EXCEPTION 'Não autorizado' USING ERRCODE='42501'; END IF; SELECT * INTO STRICT o FROM public.oportunidades WHERE id=p_oportunidade_id FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.marcas WHERE id=ANY(o.marca_ids) AND nome='PRADO') THEN RAISE EXCEPTION 'Gestão de obra exige a marca PRADO'; END IF; IF o.obra_id IS NOT NULL THEN RETURN o.obra_id; END IF; IF nullif(trim(p_nome),'') IS NULL THEN RAISE EXCEPTION 'Informe o nome da obra'; END IF; INSERT INTO public.obras(cliente_id,oportunidade_id,nome,data_fechamento) VALUES(o.cliente_id,o.id,trim(p_nome),public.hoje_sp()) RETURNING id INTO novo; UPDATE public.oportunidades SET obra_id=novo,etapa='fechado' WHERE id=o.id; RETURN novo; END $$;
CREATE VIEW public.v_alertas WITH(security_invoker=true) AS
SELECT 'cadastro_incompleto'::text tipo,'critico'::text nivel,o.id obra_id,o.oportunidade_id,l.id lote_id,'Cadastro incompleto do lote'::text mensagem,NULL::date data_ref FROM public.lotes l JOIN public.obras o ON o.id=l.obra_id WHERE NOT l.cadastro_completo AND o.finalizada_em IS NULL
UNION ALL SELECT 'medicao_sem_data','pendente',o.id,o.oportunidade_id,l.id,'Medição sem data',NULL::date FROM public.lotes l JOIN public.obras o ON o.id=l.obra_id WHERE l.status='aguardando_medicao'
UNION ALL SELECT 'medicao_atrasada','critico',o.id,o.oportunidade_id,l.id,'Medição atrasada',l.previsao_medicao FROM public.lotes l JOIN public.obras o ON o.id=l.obra_id WHERE l.previsao_medicao<public.hoje_sp() AND l.medido_em IS NULL
UNION ALL SELECT 'entrega_sem_recebimento','pendente',o.id,o.oportunidade_id,l.id,'Entrega sem confirmação de recebimento',coalesce(l.data_confirmada,l.previsao_entrega) FROM public.lotes l JOIN public.obras o ON o.id=l.obra_id CROSS JOIN public.configuracoes c WHERE c.id=1 AND coalesce(l.data_confirmada,l.previsao_entrega) BETWEEN public.hoje_sp() AND public.hoje_sp()+c.alerta_entrega_dias AND NOT l.recebimento_confirmado AND l.entregue_em IS NULL
UNION ALL SELECT 'entrega_atrasada','critico',o.id,o.oportunidade_id,l.id,'Entrega atrasada',coalesce(l.data_confirmada,l.previsao_entrega) FROM public.lotes l JOIN public.obras o ON o.id=l.obra_id WHERE coalesce(l.data_confirmada,l.previsao_entrega)<public.hoje_sp() AND l.entregue_em IS NULL
UNION ALL SELECT 'problema_obra','critico',o.id,o.oportunidade_id,NULL::uuid,o.problema_texto,NULL::date FROM public.obras o WHERE o.problema_ativo
UNION ALL SELECT 'followup_vencido','pendente',f.obra_id,f.oportunidade_id,f.lote_id,f.motivo,f.data FROM public.followups f WHERE f.status='pendente' AND f.data<public.hoje_sp();
REVOKE ALL ON public.v_alertas FROM PUBLIC,anon; GRANT SELECT ON public.v_alertas TO authenticated,service_role;
DO $$ DECLARE r record; BEGIN FOR r IN SELECT p.oid,p.prosecdef,p.proname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon',r.oid::regprocedure); IF r.proname IN ('buscar_clientes','buscar_contato_por_whatsapp','mesclar_clientes','registrar_envio','registrar_resposta','concluir_followup','cancelar_followup','remarcar_followup','marcar_problema','resolver_problema','iniciar_gestao_obra') THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated,service_role',r.oid::regprocedure); ELSIF r.proname IN('validar_configuracoes','calcular_lote','recalcular_lotes','inicializar_obra','agendar_revisao') THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated,service_role',r.oid::regprocedure); END IF; END LOOP; END $$;